basic_algorithm.code:
pub export fn fibonacci(n: u32) u32 {
  if (n <= 1) return n;
  return fibonacci(n - 1) + fibonacci(n - 2);
}

pub export fn entropy(data: [*]const u8, len: usize) f64 {
  var histogram: [256]usize = undefined;
  @memset(&histogram, 0);

  for (data[0..len]) |byte| {
    histogram[byte] += 1;
  }

  var result: f64 = 0.0;
  for (histogram) |count| {
    if (count > 0) {
      const p = @intToFloat(f64, count) / @intToFloat(f64, len);
      result -= p * std.math.log2(f64, p);
    }
  }
  return result;
}

