pub export fn compress_data(data: [*]const u8, len: usize) [*]u8 {
  var output: [65536]u8 = undefined;
  var idx: usize = 0;
  var i: usize = 0;

  while (i < len) {
    var run: u8 = 1;
    while (i + run < len and data[i] == data[i + run] and run < 255) {
      run += 1;
    }

    if (run >= 4) {
      output[idx] = 255; idx += 1;
      output[idx] = run; idx += 1;
      output[idx] = data[i]; idx += 1;
      i += run;
    } else {
      output[idx] = data[i]; idx += 1;
      i += 1;
    }
  }

  return &output;
}

