struct DataAnalyzer:
    var values: DynamicVector[Float32]

    fn __init__(inout self):
        self.values = DynamicVector[Float32]()

    fn add_value(inout self, v: Float32):
        self.values.push_back(v)

    fn mean(self) -> Float32:
        var total: Float32 = 0
        for i in range(len(self.values)):
            total += self.values[i]
        return total / Float32(len(self.values))

